"""Weekly timesheet rows, one line of text per worker."""

from typing import Dict, Iterable, List, Tuple

from hourglass.models import Shift
from hourglass.errors import ProjectError

def _check(shift: Shift) -> None:
    if not shift.worker.strip():
        raise ProjectError("shift has a blank worker name")

def _add(totals: Dict[str, Tuple[int, int]], shift: Shift):
    count, mins = totals.get(shift.worker, (0, 0))
    totals[shift.worker] = (
        count + 1,
        mins + shift.span.minutes
    )

def _tally(shifts: Iterable[Shift]):
    totals = {}
    for shift in shifts:
        _check(shift)
        _add(totals, shift)
    return totals

def _rank(item):
    name, (count, mins) = item
    return (-mins, -count, name)

def _line(name: str, count: int, mins: int) -> str:
    hours = mins / 60
    return f"{name}: {count} shifts, {hours:.1f} hours"

# ---
def timesheet_lines(shifts: Iterable[Shift]) -> List[str]:
    """One line per worker, busiest first.

    Raises ProjectError for no shifts or a blank worker name.
    """
    totals = _tally(shifts)
    if not totals:
        raise ProjectError("no shifts to report")
    ranked = sorted(totals.items(), key=_rank)
    return [_line(name, *vals) for name, vals in ranked]

